#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {1, 2, 3};

    // Correct access (precondition met)
    std::cout << v[1] << std::endl; 

    // Undefined Behavior: Index out of bounds
    // No exception guaranteed by operator[]
    // std::cout << v[100] << std::endl; 

    // Safe access (throws exception if precondition violated)
    try {
        std::cout << v.at(100) << std::endl;
    } catch (const std::out_of_range& e) {
        std::cerr << "Caught exception (safe accessor): " << e.what() << std::endl;
    }
}
